PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "products"(
  id INT,
  "Product Name*" TEXT,
  "Product Type*" TEXT,
  "Product Brand" TEXT,
  "Vendor/Supplier*" TEXT,
  "Product Strain" TEXT,
  Lineage TEXT,
  Description TEXT,
  "Weight*" TEXT,
  Units TEXT,
  Price TEXT,
  "Quantity*" TEXT,
  DOH TEXT,
  "Concentrate Type" TEXT,
  Ratio TEXT,
  JointRatio TEXT,
  State TEXT,
  "Is Sample? (yes/no)" TEXT,
  "Is MJ product?(yes/no)" TEXT,
  "Discountable? (yes/no)" TEXT,
  "Room*" TEXT,
  "Batch Number" TEXT,
  "Lot Number" TEXT,
  "Barcode*" TEXT,
  "Medical Only (Yes/No)" TEXT,
  "Med Price" TEXT,
  "Expiration Date(YYYY-MM-DD)" TEXT,
  "Is Archived? (yes/no)" TEXT,
  "THC Per Serving" TEXT,
  Allergens TEXT,
  Solvent TEXT,
  "Accepted Date" TEXT,
  "Internal Product Identifier" TEXT,
  "Product Tags (comma separated)" TEXT,
  "Image URL" TEXT,
  Ingredients TEXT,
  CombinedWeight TEXT,
  Ratio_or_THC_CBD TEXT,
  Description_Complexity INT,
  "Total THC" TEXT,
  THCA TEXT,
  CBDA TEXT,
  CBN TEXT
, normalized_name TEXT);
COMMIT;
